%%
ATOLL_rd=read_ebas_merged_STN('C:\github_trend\raw_data\merged_Lille (ATOLL) (1).nc', ATOLL_st.name); %[output:22ba42d1]

names_rd=fieldnames(ATOLL_rd);

%%
datevec(ATOLL_rd.Time(1)) % 2008 %[output:9f940d52]
datevec(ATOLL_rd.Time(end)) % 2025 %[output:8b2a28bb]
 prctile(ATOLL_rd.U370_S,[5 50 95]) % 45% %[output:3caca3b3]
plotFigControl(ATOLL_rd,ATOLL_st.name); %[output:1e699ccd] %[output:10f4dc85] %[output:667bb9b0] %[output:2ec74db1] %[output:9991ec06] %[output:1a3872a8] %[output:97128725] %[output:506177f3]
%%
% homogeneise Bs and Bbs from PM1 Aurora 3000 and PM10 Aurora 4000
% common period 4.2019-3.2020 (could be longer but the ratio PM1/PM10 could
% also has changed)

Pt=timerange('2019-04-01','2020-04-01');
ratio_med_h=nanmedian(ATOLL_rd.BsGeco0_S(Pt)./ATOLL_rd.BsGeco1_S(Pt)) % 1.21 %[output:79d6ac4d]
ratio_STN_h=nanstd(ATOLL_rd.BsGeco0_S(Pt)./ATOLL_rd.BsGeco1_S(Pt)) % 0.31 %[output:432987fb]
ratio_mean_h=nanmean(ATOLL_rd.BsGeco0_S(Pt)./ATOLL_rd.BsGeco1_S(Pt)) %1.21 %[output:6ea38c29]
ratio_mean=nanmean(ATOLL_rd.BsGeco0_S(Pt))/nanmean(ATOLL_rd.BsGeco1_S(Pt)) % 1.12 %[output:765f9b02]
ratio_median=nanmedian(ATOLL_rd.BsGeco0_S(Pt))/nanmedian(ATOLL_rd.BsGeco1_S(Pt)) %1.216 %[output:21f9c1c8]
figure; %[output:71faad28]
plot(ATOLL_rd.BsGeco1_S(Pt),ATOLL_rd.BsGeco0_S(Pt),'.'); %[output:71faad28]

% fit between both data: 1) slope 0.92x+6.8, 
fit_test=robustfit(ATOLL_rd.BsGeco1_S(Pt),ATOLL_rd.BsGeco0_S(Pt)); % 1) y coor=1.06, slope=1.16
fit_test_Bbs=robustfit(ATOLL_rd.BbsGeco1_S(Pt),ATOLL_rd.BbsGeco0_S(Pt)); % 1) y coor=1.06, slope=1.16

%%
c_eco1_eco0=1.15; 
% for Bbs:
c_eco1_eco0_Bbs=0.90;
%%
P1=timerange('2016-01-01','2017-03-01');
P2=timerange('2017-08-01','2019-03-15');
P3=timerange('2019-03-15','2026-01-01');

ATOLL_rd.BsG_Sh=NaN(size(ATOLL_rd.BsGeco0_S));
ATOLL_rd.BsG_Sh(P1)=ATOLL_rd.BsGeco_S(P1);
ATOLL_rd.BsG_Sh(P2)=ATOLL_rd.BsGeco1_S(P2).* c_eco1_eco0;
ATOLL_rd.BsG_Sh(P3)=ATOLL_rd.BsGeco0_S(P3);

ATOLL_rd.BsB_Sh=NaN(size(ATOLL_rd.BsB0_S));
ATOLL_rd.BsB_Sh(P1)=ATOLL_rd.BsB_S(P1);
ATOLL_rd.BsB_Sh(P2)=ATOLL_rd.BsB1_S(P2).* c_eco1_eco0;
ATOLL_rd.BsB_Sh(P3)=ATOLL_rd.BsB0_S(P3);


ATOLL_rd.BsR_Sh=NaN(size(ATOLL_rd.BsReco0_S));
ATOLL_rd.BsR_Sh(P1)=ATOLL_rd.BsReco_S(P1);
ATOLL_rd.BsR_Sh(P2)=ATOLL_rd.BsReco1_S(P2).* c_eco1_eco0;
ATOLL_rd.BsR_Sh(P3)=ATOLL_rd.BsReco0_S(P3);
%Bbs

ATOLL_rd.BbsG_Sh=NaN(size(ATOLL_rd.BbsGeco0_S));
ATOLL_rd.BbsG_Sh(P1)=ATOLL_rd.BbsGeco_S(P1);
ATOLL_rd.BbsG_Sh(P2)=ATOLL_rd.BbsGeco1_S(P2).* c_eco1_eco0_Bbs;
ATOLL_rd.BbsG_Sh(P3)=ATOLL_rd.BbsGeco0_S(P3);

ATOLL_rd.BbsB_Sh=NaN(size(ATOLL_rd.BbsB0_S));
ATOLL_rd.BbsB_Sh(P1)=ATOLL_rd.BbsB_S(P1);
ATOLL_rd.BbsB_Sh(P2)=ATOLL_rd.BbsB1_S(P2).* c_eco1_eco0_Bbs;
ATOLL_rd.BbsB_Sh(P3)=ATOLL_rd.BbsB0_S(P3);


ATOLL_rd.BbsR_Sh=NaN(size(ATOLL_rd.BbsReco0_S));
ATOLL_rd.BbsR_Sh(P1)=ATOLL_rd.BbsReco_S(P1);
ATOLL_rd.BbsR_Sh(P2)=ATOLL_rd.BbsReco1_S(P2).* c_eco1_eco0_Bbs;
ATOLL_rd.BbsR_Sh(P3)=ATOLL_rd.BbsReco0_S(P3);

%%
% BP detection for scat coef and backscat

names_sc={'BsB_Sh', 'BsG_Sh', 'BsR_Sh'};
