%%
% BP detection for abs
names_abs={'BaR_A_maap','BaR_Ah'};
break_ATOLL_abs_BP=change_point_analysis_Def(ATOLL_rd,names_abs,0.05,'ATOLL','Absorption'); %[output:99b77055] %[output:08945241] %[output:58072e56] %[output:7c11ed75]
